//! 🗃️ Retains the published presentation while its original seed, tick and retired children advance privately.
use super::{ToolRunPresentation,ToolRunPresentationBody,seed::ToolRunPresentationSeed,update::ToolRunPresentationUpdate};
use super::super::{ToolRunIdentity,ToolRunState,ToolRunTick,entities::{ToolRunEntityEditGrant,ToolRunEntityEditProgress}};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::{RetireOwned,RetirementCursor,controlled::ControlledRetirement}};
use std::mem::{ManuallyDrop,size_of};

#[derive(semio_framework_value::RetireOwned)]
struct State{seed:Option<ToolRunPresentationSeed>,published:Option<ToolRunPresentation>,update:Option<ToolRunPresentationUpdate>,candidate:Option<ToolRunPresentation>,displaced:Option<ToolRunPresentation>,seed_close:Option<ControlledRetirement<ToolRunPresentationSeed>>,update_close:Option<ControlledRetirement<ToolRunPresentationUpdate>>,displaced_close:Option<ControlledRetirement<ToolRunPresentation>>,pending_cancel:bool,cancelled:bool}
pub struct ToolRunPresentationSlot{state:ManuallyDrop<State>,transferred:bool}
fn demands<T:RetireOwned>(owner:&ControlledRetirement<T>,body:usize)->Result<RetirementDemand,ValueError>{if owner.terminal_is_empty(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<ControlledRetirement<T>>>(),depth:1,..Default::default()});}let copy=owner.next_copy_byte_demand()?;Ok(RetirementDemand{copy_bytes:copy,capacity_bytes:owner.next_capacity_byte_demand(body.max(copy))?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?})}
impl ToolRunPresentationSlot{
 pub fn new(tool_id:String,identity:ToolRunIdentity,state:ToolRunState)->Self{Self{state:ManuallyDrop::new(State{seed:Some(ToolRunPresentationSeed::new(tool_id,identity,state)),published:None,update:None,candidate:None,displaced:None,seed_close:None,update_close:None,displaced_close:None,pending_cancel:false,cancelled:false}),transferred:false}}
 pub fn ready(&self)->bool{let s=&*self.state;!s.cancelled&&!s.pending_cancel&&s.published.is_some()&&s.seed.is_none()&&s.update.is_none()&&s.candidate.is_none()&&s.displaced.is_none()&&s.seed_close.is_none()&&s.update_close.is_none()&&s.displaced_close.is_none()}
 pub fn body(&self)->Option<&ToolRunPresentationBody>{self.state.published.as_ref().map(ToolRunPresentation::body)}
 pub fn identifier(&self)->&str{if let Some(body)=self.body(){body.tool_id.get()}else if let Some(candidate)=self.state.candidate.as_ref(){candidate.body().tool_id.get()}else{self.state.seed.as_ref().expect("original presentation seed remains retained before publication").original_identifier()}}
 pub fn capture(&self,grant:RetainedCloneGrant)->Result<Option<(ToolRunPresentation,RetainedCloneProgress)>,ValueError>{if self.state.cancelled{return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"closing original presentation cannot issue new captures"));}self.state.published.as_ref().map(|source|source.capture(grant)).transpose()}
 pub fn borrowed_view(&self,identity:ToolRunIdentity,state:ToolRunState)->Option<super::ToolRunView<'_>>{self.state.published.as_ref().map(|source|source.borrowed_view(identity,state))}
 pub fn capture_view(&self,identity:ToolRunIdentity,state:ToolRunState,grant:RetainedCloneGrant)->Result<Option<(super::ToolRunCapturedView,RetainedCloneProgress)>,ValueError>{if self.state.cancelled{return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"closing original presentation cannot issue new context capture"));}self.state.published.as_ref().map(|source|source.capture_view(identity,state,grant)).transpose()}
 pub fn cancel_pending(&mut self){if self.state.update.is_some()||self.state.candidate.is_some(){self.state.pending_cancel=true;if let Some(update)=self.state.update.as_mut(){update.cancel();}}}
 pub fn cancel(&mut self){self.state.cancelled=true;if let Some(seed)=self.state.seed.as_mut(){seed.cancel();}if let Some(update)=self.state.update.as_mut(){update.cancel();}}
 pub fn tick_admission_demands()->RetirementDemand{RetirementDemand{copy_bytes:ToolRunPresentation::capture_copy_bytes()+size_of::<ToolRunTick>()+size_of::<ToolRunPresentationUpdate>(),depth:1,..Default::default()}}
 pub fn begin_tick(&mut self,tick:ToolRunTick,end:u32,state:ToolRunState,rate:f32,conflicts:u32,grant:RetainedCloneGrant)->Result<((),RetainedCloneProgress),(ValueError,ToolRunTick)>{let quote=Self::tick_admission_demands();if !self.ready(){return Err((ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original presentation slot still owns pending work"),tick));}if grant.maximum_items==0||grant.maximum_copy_bytes<quote.copy_bytes||grant.maximum_depth<quote.depth{return Err((ValueError::literal(ValueRefusalKind::OwnershipLimit,"original tick and presentation handoff are not funded"),tick));}let original=self.state.published.as_ref().unwrap();if tick.identity.id!=original.body().progress.identity.id{return Err((ValueError::literal(ValueRefusalKind::InvalidValue,"incoming original tick belongs to another run"),tick));}match original.capture(grant){Ok((capture,mut receipt))=>{self.state.update=Some(ToolRunPresentationUpdate::new(capture,tick,end,state,rate,conflicts));receipt.copied_bytes=quote.copy_bytes;Ok(((),receipt))},Err(error)=>Err((error,tick))}}
 pub fn edit_capacity_bound(&self)->Result<usize,ValueError>{self.state.update.as_ref().map_or(Ok(0),ToolRunPresentationUpdate::edit_capacity_bound)}
 pub fn next_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{let s=&*self.state;if s.cancelled||self.ready(){return Ok(Default::default());}if let Some(owner)=s.seed_close.as_ref(){return demands(owner,body);}if let Some(owner)=s.update_close.as_ref(){return demands(owner,body);}if let Some(owner)=s.displaced_close.as_ref(){return demands(owner,body);}if s.displaced.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if s.pending_cancel&&s.candidate.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if let Some(seed)=s.seed.as_ref(){return if s.candidate.is_some(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentationSeed>(),depth:1,..Default::default()})}else if seed.complete(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()})}else{seed.next_demands()};}if let Some(update)=s.update.as_ref(){return if s.pending_cancel||s.candidate.is_some(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentationUpdate>(),depth:1,..Default::default()})}else if update.complete(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()})}else{update.next_demands(body)};}if s.candidate.is_some(){return Ok(RetirementDemand{copy_bytes:3*size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if s.pending_cancel{return Ok(RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()});}Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation slot has no original pending owner"))}
 pub fn advance(&mut self,grant:ToolRunEntityEditGrant)->Result<ToolRunEntityEditProgress,ValueError>{
  if self.state.cancelled||self.ready()||grant.retirement.maximum_items==0{return Ok(Default::default());}let quote=self.next_demands(grant.retirement.maximum_copy_bytes)?;if quote.copy_bytes>grant.retirement.maximum_copy_bytes||quote.capacity_bytes>grant.retirement.maximum_capacity_bytes||quote.release_bytes>grant.retirement.maximum_release_bytes||quote.depth>grant.retirement.maximum_depth{return Ok(Default::default());}let s=&mut*self.state;let mut receipt=ToolRunEntityEditProgress{retirement:RetainedCloneProgress{copied_items:1,copied_bytes:quote.copy_bytes,..Default::default()},..Default::default()};
  macro_rules! close {($field:ident)=>{if let Some(owner)=s.$field.as_mut(){if !owner.terminal_is_empty(){return owner.step(grant.retirement).map(|step|ToolRunEntityEditProgress{retirement:step.progress(),..Default::default()});}s.$field=None;return Ok(receipt);}};}
  close!(seed_close);close!(update_close);close!(displaced_close);
  if let Some(displaced)=s.displaced.take(){match ControlledRetirement::new(displaced){Ok(close)=>s.displaced_close=Some(close),Err((error,displaced))=>{s.displaced=Some(displaced);return Err(error);}}return Ok(receipt);}
  if s.pending_cancel&&s.candidate.is_some(){s.displaced=s.candidate.take();return Ok(receipt);}if let Some(seed)=s.seed.as_mut(){if s.candidate.is_some(){let seed=s.seed.take().unwrap();match ControlledRetirement::new(seed){Ok(close)=>s.seed_close=Some(close),Err((error,seed))=>{s.seed=Some(seed);return Err(error);}}}else if seed.complete(){let(output,progress)=seed.take_output(grant.retirement)?.unwrap();s.candidate=Some(output);receipt.retirement=progress;}else{receipt.retirement=seed.advance(grant.retirement)?;}return Ok(receipt);}
  if let Some(update)=s.update.as_mut(){if s.pending_cancel||s.candidate.is_some(){let update=s.update.take().unwrap();match ControlledRetirement::new(update){Ok(close)=>s.update_close=Some(close),Err((error,update))=>{s.update=Some(update);return Err(error);}}}else if update.complete(){let(output,progress)=update.take_output(grant.retirement)?.unwrap();s.candidate=Some(output);receipt.retirement=progress;}else{return update.advance(grant);}return Ok(receipt);}
  if let Some(candidate)=s.candidate.take(){s.displaced=s.published.replace(candidate);return Ok(receipt);}if s.pending_cancel{s.pending_cancel=false;return Ok(receipt);}Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation slot cannot find its funded transition"))
 }
}
impl RetireOwned for ToolRunPresentationSlot{fn retirement(mut self)->Box<dyn RetirementCursor>{self.transferred=true;unsafe{ManuallyDrop::take(&mut self.state)}.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.state.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}fn retirement_element_copy_bytes()->usize{size_of::<Self>()}}
impl Drop for ToolRunPresentationSlot{fn drop(&mut self){if !self.transferred&&!std::thread::panicking(){panic!("original presentation slot requires controlled retirement")}}}
